<?php require dirname(__DIR__).'/core/bootstrap.php';$u=auth(true);$admin=true;$id=(int)($_GET['id']??0);$o=$id?one('SELECT o.*,u.name,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?',[$id]):null;if($id&&!$o){http_response_code(404);exit('Pedido não encontrado.');}$error='';if(is_post()&&$o){verify_csrf();try{$status=input('status',30);if(!in_array($status,['requested','quoted','paid','delivered','cancelled'],true))throw new InvalidArgumentException('Status inválido.');$v=input('amount',30);$amount=$v===''?null:parse_price($v);if(in_array($status,['paid','delivered'],true)&&($amount===null||!isset($_POST['checked_payment'])))throw new InvalidArgumentException('Informe o valor e confirme a conferência do pagamento antes de registrar a venda.');run('UPDATE orders SET status=?,amount=?,updated_at=? WHERE id=?',[$status,$amount,date('Y-m-d H:i:s'),$id]);audit('pedido_status','Pedido #'.$id.' status '.$status);flash('Pedido atualizado. A licença e a liberação dos arquivos são gerenciadas em Licenças.');go('admin/pedidos.php?id='.$id);}catch(InvalidArgumentException $ex){$error=$ex->getMessage();}}require ROOT.'/includes/panel.php';?><h1>Pedidos e vendas.</h1><?php if($error):?><div class="errors"><?=e($error)?></div><?php endif;if($o):?><article class="card"><h2>Pedido #<?=$id?> — <?=e($o['product_name'])?></h2><p><?=e($o['name'])?> • <?=e($o['email'])?><br>Domínio: <?=e($o['domain'])?></p><p><?=e($o['notes'])?></p></article><form method="post"><?php csrf();?><div class="grid-two"><label class="field">Valor combinado em R$<input name="amount" value="<?=e($o['amount']===null?'':number_format((float)$o['amount'],2,',',''))?>" placeholder="299,90"></label><label class="field">Status<select name="status"><?php foreach(['requested'=>'Solicitado','quoted'=>'Proposta disponível','paid'=>'Pagamento confirmado','delivered'=>'Entregue','cancelled'=>'Cancelado'] as $k=>$v):?><option value="<?=$k?>" <?=$o['status']===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label></div><label class="check"><input type="checkbox" name="checked_payment">Conferi o pagamento externamente (necessário para pago / entregue).</label><button class="primary">Atualizar pedido</button></form><br><a class="textlink" href="<?=e(url('admin/licencas.php?novo=1&pedido='.$id))?>">Emitir licença para este pedido ↗</a><?php else:?><div class="table-wrap"><table><tr><th>Pedido</th><th>Cliente</th><th>Produto</th><th>Valor</th><th>Status</th></tr><?php foreach(rows('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 300') as $o):?><tr><td><a href="<?=e(url('admin/pedidos.php?id='.$o['id']))?>">#<?=$o['id']?></a></td><td><?=e($o['name'])?></td><td><?=e($o['product_name'])?></td><td><?=e(money($o['amount']))?></td><td><?=e($o['status'])?></td></tr><?php endforeach;?></table></div><?php endif;require ROOT.'/includes/endpanel.php';?>
